    // GIF Support etc.
    //
    //---------------------------------------------------------------------
    // byteArrayOutputStream
    //---------------------------------------------------------------------
    var byteArrayOutputStream = function() {
        var _bytes = [];
        var _this = {};
        _this.writeByte = function(b) {
            _bytes.push(b & 0xff);
        };
        _this.writeShort = function(i) {
            _this.writeByte(i);
            _this.writeByte(i >>> 8);
        };
        _this.writeBytes = function(b, off, len) {
            off = off || 0;
            len = len || b.length;
            for(var i = 0; i < len; i += 1)_this.writeByte(b[i + off]);
        };
        _this.writeString = function(s) {
            for(var i = 0; i < s.length; i += 1)_this.writeByte(s.charCodeAt(i));
        };
        _this.toByteArray = function() {
            return _bytes;
        };
        _this.toString = function() {
            var s = '';
            s += '[';
            for(var i = 0; i < _bytes.length; i += 1){
                if (i > 0) s += ',';
                s += _bytes[i];
            }
            s += ']';
            return s;
        };
        return _this;
    };
    //---------------------------------------------------------------------
    // base64EncodeOutputStream
    //---------------------------------------------------------------------
    var base64EncodeOutputStream = function() {
        var _buffer = 0;
        var _buflen = 0;
        var _length = 0;
        var _base64 = '';
        var _this = {};
        var writeEncoded = function(b) {
            _base64 += String.fromCharCode(encode(b & 0x3f));
        };
        var encode = function(n) {
            if (n < 0) ;
            else if (n < 26) return 0x41 + n;
            else if (n < 52) return 0x61 + (n - 26);
            else if (n < 62) return 0x30 + (n - 52);
            else if (n == 62) return 0x2b;
            else if (n == 63) return 0x2f;
            throw 'n:' + n;
        };
        _this.writeByte = function(n) {
            _buffer = _buffer << 8 | n & 0xff;
            _buflen += 8;
            _length += 1;
            while(_buflen >= 6){
                writeEncoded(_buffer >>> _buflen - 6);
                _buflen -= 6;
            }
        };
        _this.flush = function() {
            if (_buflen > 0) {
                writeEncoded(_buffer << 6 - _buflen);
                _buffer = 0;
                _buflen = 0;
            }
            if (_length % 3 != 0) {
                // padding
                var padlen = 3 - _length % 3;
                for(var i = 0; i < padlen; i += 1)_base64 += '=';
            }
        };
        _this.toString = function() {
            return _base64;
        };
        return _this;
    };
    //---------------------------------------------------------------------
    // base64DecodeInputStream
    //---------------------------------------------------------------------
    var base64DecodeInputStream = function(str) {
        var _str = str;
        var _pos = 0;
        var _buffer = 0;
        var _buflen = 0;
        var _this = {};
        _this.read = function() {
            while(_buflen < 8){
                if (_pos >= _str.length) {
                    if (_buflen == 0) return -1;
                    throw 'unexpected end of file./' + _buflen;
                }
                var c = _str.charAt(_pos);
                _pos += 1;
                if (c == '=') {
                    _buflen = 0;
                    return -1;
                } else if (c.match(/^\s$/)) continue;
                _buffer = _buffer << 6 | decode(c.charCodeAt(0));
                _buflen += 6;
            }
            var n = _buffer >>> _buflen - 8 & 0xff;
            _buflen -= 8;
            return n;
        };
        var decode = function(c) {
            if (0x41 <= c && c <= 0x5a) return c - 0x41;
            else if (0x61 <= c && c <= 0x7a) return c - 0x61 + 26;
            else if (0x30 <= c && c <= 0x39) return c - 0x30 + 52;
            else if (c == 0x2b) return 62;
            else if (c == 0x2f) return 63;
            else throw 'c:' + c;
        };
        return _this;
    };
