            // Global Color Map
            // black
            out.writeByte(0x00);
            out.writeByte(0x00);
            out.writeByte(0x00);
            // white
            out.writeByte(0xff);
            out.writeByte(0xff);
            out.writeByte(0xff);
            //---------------------------------
            // Image Descriptor
            out.writeString(',');
            out.writeShort(0);
            out.writeShort(0);
            out.writeShort(_width);
            out.writeShort(_height);
